    root = {}
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        # ignore leading 'json' if present
        # handle lines like json = {}; or json.foo = "x";
        m = re.match(r'^(json(?:[\.|\[].*)?)\s*=\s*(.*?);\s*$', line)
        if not m:
            # maybe json stream lines like [[],{}]
            try:
                arr = json.loads(line)
                if isinstance(arr, list) and len(arr) == 2:
                    path = arr[0]
                    val = arr[1]
                    set_path(root, path, val)
                continue
            except Exception:
                continue
        path_str = m.group(1)
        val_str = m.group(2)
        if path_str == 'json':
            # root declaration
            continue
        try:
            path = parse_path(path_str)
        except Exception:
            continue
        try:
            val = json.loads(val_str)
        except Exception:
            # maybe it's unquoted string? treat as string
            val = val_str.strip('"')
        set_path(root, path, val)
    return root


